import { MakeLogicType, actions, kea, path, reducers } from 'kea'

import type { AgentPromptDestination } from './AgentPromptButton'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface agentPromptButtonLogicValues {
    rememberedActionKeys: Record<string, string>
    rememberedAgentKey: AgentPromptDestination | null
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface agentPromptButtonLogicActions {
    rememberAction: (
        storageKey: string,
        actionKey: string
    ) => {
        actionKey: string
        storageKey: string
    }
    rememberAgent: (agentKey: AgentPromptDestination) => {
        agentKey: AgentPromptDestination
    }
}

export type agentPromptButtonLogicType = MakeLogicType<agentPromptButtonLogicValues, agentPromptButtonLogicActions>

export const agentPromptButtonLogic = kea<agentPromptButtonLogicType>([
    // pinned: the persisted localStorage keys derive from this path, so changing it resets every remembered choice
    path(['lib', 'components', 'AgentPromptButton', 'agentPromptButtonLogic']),
    actions({
        rememberAgent: (agentKey: AgentPromptDestination) => ({ agentKey }),
        rememberAction: (storageKey: string, actionKey: string) => ({ storageKey, actionKey }),
    }),
    reducers({
        rememberedAgentKey: [
            null as AgentPromptDestination | null,
            { persist: true },
            {
                rememberAgent: (_, { agentKey }) => agentKey,
            },
        ],
        rememberedActionKeys: [
            {} as Record<string, string>,
            { persist: true },
            {
                rememberAction: (state, { storageKey, actionKey }) => ({ ...state, [storageKey]: actionKey }),
            },
        ],
    }),
])
